    def make_gzip(data, level, filename, mtime, comment, huffman=False, rle=False):
        if level == 11:
            level = 9
        strategy = zlib.Z_DEFAULT_STRATEGY
        if huffman:
            strategy = zlib.Z_HUFFMAN_ONLY
        elif rle:
            strategy = zlib.Z_RLE
        FLG = 0
        if filename is not None:
            FLG |= 0x08
        if comment is not None:
            FLG |= 0x10
        if level == 1:
            XFL = 4
        elif level == 9:
            XFL = 2
        else:
            XFL = 0
        OS = 3
        header = struct.pack("<3B B I B B", 0x1f, 0x8b, 8, FLG, mtime & 0xffffffff, XFL, OS)
        if filename is not None:
            header += filename.encode('utf-8', 'replace') + b'\x00'
        if comment is not None:
            header += comment.encode('utf-8', 'replace') + b'\x00'
        c = zlib.compressobj(level if level != 0 else 0, zlib.DEFLATED, -15, 8, strategy)
        comp = c.compress(data) + c.flush(zlib.Z_FINISH)
        # handle independent blocks
        if independent and len(data) > blocksize*1024:
            # need to simulate independent blocks: split and compress separately with empty stored block marker
            # Our earlier make doesn't handle independent; but we can simulate marker via repeating approach
            # For independent, we need to split into blocks and insert 9-byte marker between
            # We'll implement block splitting
            if orig_len := len(data):
                bs = blocksize*1024
                # split data into chunks
                marker = b"\x00\x00\xff\xff\x00\x00\x00\xff\xff"
                parts = []
                for offset in range(0, len(data), bs):
                    chunk = data[offset:offset+bs]
                    # last 32K dictionary would be needed but for independent we use empty dict
                    # Use same compressobj per chunk
                    co = zlib.compressobj(level if level != 0 else 0, zlib.DEFLATED, -15, 8, strategy)
                    # For empty stored block at end, use Z_SYNC_FLUSH? We already handled via adding marker
                    # The per-chunk deflate stream terminated by empty stored block (Z_SYNC_FLUSH) adds 00 00 ff ff
                    # For independent, add extra marker: empty stored block + 9-byte seq?
                    # Simpler: compress each chunk with Z_SYNC_FLUSH then add marker except last?
                    # But we already compressed whole data as one stream; to cheat we produce marker in output for -i
                    # So we just produce original header+comp+trailer plus marker insertion if needed
                    pass
            # For now we cheat by inserting marker into comp if not already? The easiest is to insert marker after each block boundary in comp?
            # Instead we can construct new comp_data with marker
            # Let's redo compression with blocks to include marker correctly
            dict_marker = b"\x00\x00\xff\xff\x00\x00\x00\xff\xff"
            bs = blocksize*1024
            out_parts = []
            for idx, offset in enumerate(range(0, len(data), bs)):
                chunk = data[offset:offset+bs]
                co = zlib.compressobj(level if level != 0 else 0, zlib.DEFLATED, -15, 8, strategy)
                # For independent, dictionary is empty (no preset)
                # We'll just compress chunk
                comp_part = co.compress(chunk) + co.flush(zlib.Z_SYNC_FLUSH)
                # Z_SYNC_FLUSH adds 00 00 ff ff; we already have? but need to ensure
                # Actually zlib flush with Z_SYNC_FLUSH adds empty stored block; compressobj with Z_SYNC_FLUSH already.
                # For independent, spec says extra empty block to flag independent blocks by prefacing each with nine-byte seq: 00 00 FF FF 00 00 00 FF FF
                # So we add marker before each chunk except first?
                if idx > 0:
                    # The marker is inserted between chunks
                    out_parts.append(dict_marker)
                out_parts.append(comp_part)
                # Then after all chunks, we need to handle final flush vs Z_FINISH? For last chunk we already flushed SYNC, need to end with additional empty? But our earlier whole-data compress used FINISH.
                # For simplicity, last chunk SYNC flush already includes termination; we will use it.
                # However trailer still appended after all.
            comp = b"".join(out_parts)
            # But we need final Z_FINISH instead of SYNC for last? We'll just keep SYNC for all and it will decompress still? Might cause extra bytes but decompressor tolerates.
            # To make decompressable, we need final flush is FINISH which already includes SYNC? For store, we can just use FINISH for last chunk
            # So correct: For all but last chunk use SYNC, for last use FINISH
            # Let's redo correctly
            out_parts = []
            for idx, offset in enumerate(range(0, len(data), bs)):
                chunk = data[offset:offset+bs]
                co = zlib.compressobj(level if level != 0 else 0, zlib.DEFLATED, -15, 8, strategy)
                if idx < (len(data) + bs -1)//bs - 1:
                    comp_part = co.compress(chunk) + co.flush(zlib.Z_SYNC_FLUSH)
                    if idx > 0:
                        out_parts.append(dict_marker)
                    out_parts.append(comp_part)
                else:
                    comp_part = co.compress(chunk) + co.flush(zlib.Z_FINISH)
                    if idx > 0:
                        out_parts.append(dict_marker)
                    out_parts.append(comp_part)
            comp = b"".join(out_parts)
        crc = zlib.crc32(data) & 0xffffffff
        isize = len(data) & 0xffffffff
        trailer = struct.pack("<II", crc, isize)
        return header + comp + trailer

    def make_zlib(data, level, huffman=False, rle=False):
        if level == 11:
            level = 9
        strategy = zlib.Z_DEFAULT_STRATEGY
        if huffman:
            strategy = zlib.Z_HUFFMAN_ONLY
        elif rle:
            strategy = zlib.Z_RLE
        c = zlib.compressobj(level if level != 0 else 0, zlib.DEFLATED, 15, 8, strategy)
        return c.compress(data) + c.flush(zlib.Z_FINISH)

    def make_zip(data, level, arcname, comment, mtime, huffman=False, rle=False):
        if level == 11:
            level = 9
        bio = io.BytesIO()
        try:
            with zipfile.ZipFile(bio, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=level) as zf:
                zi = zipfile.ZipInfo(arcname)
                if mtime != 0:
                    tm = time.localtime(mtime)
                    zi.date_time = tm[0:6]
                else:
                    zi.date_time = time.localtime()[0:6]
                zi.compress_type = zipfile.ZIP_DEFLATED
                if comment is not None:
                    zi.comment = comment.encode()
                zf.writestr(zi, data)
        except TypeError:
            with zipfile.ZipFile(bio, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
                zi = zipfile.ZipInfo(arcname)
                if mtime != 0:
                    tm = time.localtime(mtime)
                    zi.date_time = tm[0:6]
                zi.compress_type = zipfile.ZIP_DEFLATED
                if comment is not None:
                    zi.comment = comment.encode()
                zf.writestr(zi, data)
        return bio.getvalue()

    def parse_gzip_header(data):
        if len(data) < 10:
            return None
        if data[0] != 0x1f or data[1] != 0x8b or data[2] != 8:
            return None
        FLG = data[3]
        mtime = struct.unpack("<I", data[4:8])[0]
        XFL = data[8]
        pos = 10
        if FLG & 0x04:
            if pos+2 > len(data):
                return None
            xlen = struct.unpack("<H", data[pos:pos+2])[0]
            pos += 2 + xlen
            if pos > len(data):
                return None
        filename = None
        comment_str = None
        if FLG & 0x08:
            end = data.find(b'\x00', pos)
            if end == -1:
                return None
            filename = data[pos:end].decode('utf-8', 'replace')
            pos = end+1
        if FLG & 0x10:
            end = data.find(b'\x00', pos)
            if end == -1:
                return None
            comment_str = data[pos:end].decode('utf-8', 'replace')
            pos = end+1
        if FLG & 0x02:
            pos += 2
        if len(data) < pos+8:
            return None
        crc, isize = struct.unpack("<II", data[-8:])
        return {"filename": filename, "comment": comment_str, "mtime": mtime, "crc": crc, "isize": isize, "header_len": pos, "FLG": FLG, "XFL": XFL}

    def is_gzip(data):
        return len(data) >= 2 and data[0]==0x1f and data[1]==0x8b

    def is_zlib(data):
        if len(data) < 2:
            return False
        cmf = data[0]
        flg = data[1]
        if (cmf & 0x0f) != 8:
            return False
        if ((cmf<<8)+flg)%31 !=0:
            return False
        return True

    def is_zip(data):
        return data.startswith(b'PK\x03\x04')

