                        rsyncable=True; j+=1
                    elif ch=='S':
                        if j+1<len(arg):
                            do_abort("invalid usage: -S must be followed by space")
                        if i+1>=len(combined) or combined[i+1].startswith("-"):
                            do_abort("missing parameter after -S")
                        suffix=combined[i+1]; i+=1; j=len(arg); break
                    elif ch=='t':
                        test_mode=True; j+=1
                    elif ch=='U':
                        rle=True; j+=1
                    elif ch=='v':
                        verbose=True; j+=1
                    elif ch=='V':
                        if verbose:
                            sys.stdout.write(VERSION_TEXT+VERSION_VERBOSE_EXTRA)
                        else:
                            sys.stdout.write(VERSION_TEXT)
                        sys.exit(0)
                    elif ch=='Y':
                        synchronous=True; j+=1
                    elif ch=='z':
                        zlib_flag=True; j+=1
                    else:
                        if ch=='Z':
                            do_abort(f"invalid option: LZW output not supported: -{ch}")
                        else:
                            do_abort(f"invalid option: -{ch}")
            i+=1; continue
        else:
            files.append(arg); i+=1; continue
