    def make_gzip(data, level, filename, mtime, comment, huffman=False, rle=False):
        if level==11: level=9
        strategy=zlib.Z_DEFAULT_STRATEGY
        if huffman: strategy=zlib.Z_HUFFMAN_ONLY
        elif rle: strategy=zlib.Z_RLE
        FLG=0
        if filename is not None: FLG|=0x08
        if comment is not None: FLG|=0x10
        if level==1: XFL=4
        elif level==9: XFL=2
        else: XFL=0
        OS=3
        header=struct.pack("<3B B I B B", 0x1f,0x8b,8,FLG,mtime&0xffffffff,XFL,OS)
        if filename is not None:
            header+=filename.encode('utf-8','replace')+b'\x00'
        if comment is not None:
            header+=comment.encode('utf-8','replace')+b'\x00'
        # handle independent blocks
        if independent and len(data)>blocksize*1024:
            bs=blocksize*1024
            dict_marker=b"\x00\x00\xff\xff\x00\x00\x00\xff\xff"
            parts=[]
            chunks=[data[o:o+bs] for o in range(0,len(data),bs)]
            for idx, chunk in enumerate(chunks):
                co=zlib.compressobj(level if level!=0 else 0, zlib.DEFLATED, -15, 8, strategy)
                if idx < len(chunks)-1:
                    comp_part=co.compress(chunk)+co.flush(zlib.Z_SYNC_FLUSH)
                    if idx>0:
                        parts.append(dict_marker)
                    parts.append(comp_part)
                else:
                    comp_part=co.compress(chunk)+co.flush(zlib.Z_FINISH)
                    if idx>0:
                        parts.append(dict_marker)
                    parts.append(comp_part)
            comp=b"".join(parts)
        else:
            c=zlib.compressobj(level if level!=0 else 0, zlib.DEFLATED, -15, 8, strategy)
            comp=c.compress(data)+c.flush(zlib.Z_FINISH)
        crc=zlib.crc32(data)&0xffffffff
        isize=len(data)&0xffffffff
        trailer=struct.pack("<II",crc,isize)
        return header+comp+trailer
    def make_zlib(data, level, huffman=False, rle=False):
        if level==11: level=9
        strategy=zlib.Z_DEFAULT_STRATEGY
        if huffman: strategy=zlib.Z_HUFFMAN_ONLY
        elif rle: strategy=zlib.Z_RLE
        c=zlib.compressobj(level if level!=0 else 0, zlib.DEFLATED, 15, 8, strategy)
        return c.compress(data)+c.flush(zlib.Z_FINISH)
    def make_zip(data, level, arcname, comment, mtime, huffman=False, rle=False):
        if level==11: level=9
        bio=io.BytesIO()
        try:
            with zipfile.ZipFile(bio,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=level) as zf:
                zi=zipfile.ZipInfo(arcname)
                if mtime!=0:
                    tm=time.localtime(mtime)
                    zi.date_time=tm[0:6]
                else:
                    zi.date_time=time.localtime()[0:6]
                zi.compress_type=zipfile.ZIP_DEFLATED
                if comment is not None:
                    zi.comment=comment.encode()
                zf.writestr(zi,data)
        except TypeError:
            with zipfile.ZipFile(bio,'w',compression=zipfile.ZIP_DEFLATED) as zf:
                zi=zipfile.ZipInfo(arcname)
                if mtime!=0:
                    tm=time.localtime(mtime)
                    zi.date_time=tm[0:6]
                zi.compress_type=zipfile.ZIP_DEFLATED
                if comment is not None:
                    zi.comment=comment.encode()
                zf.writestr(zi,data)
        return bio.getvalue()
    def parse_gzip_header(data):
        if len(data)<10: return None
        if data[0]!=0x1f or data[1]!=0x8b or data[2]!=8: return None
        FLG=data[3]; mtime=struct.unpack("<I",data[4:8])[0]
        pos=10
        if FLG & 0x04:
            if pos+2>len(data): return None
            xlen=struct.unpack("<H",data[pos:pos+2])[0]
            pos+=2+xlen
            if pos>len(data): return None
        filename=None; comment_str=None
        if FLG & 0x08:
            end=data.find(b'\x00',pos)
            if end==-1: return None
            filename=data[pos:end].decode('utf-8','replace'); pos=end+1
        if FLG & 0x10:
            end=data.find(b'\x00',pos)
            if end==-1: return None
            comment_str=data[pos:end].decode('utf-8','replace'); pos=end+1
        if FLG & 0x02:
            pos+=2
        if len(data)<pos+8: return None
        crc,isize=struct.unpack("<II",data[-8:])
        return {"filename":filename,"comment":comment_str,"mtime":mtime,"crc":crc,"isize":isize,"header_len":pos,"FLG":FLG}
    def is_gzip(data): return len(data)>=2 and data[0]==0x1f and data[1]==0x8b
    def is_zlib(data):
        if len(data)<2: return False
        cmf=data[0]; flg=data[1]
        if (cmf & 0x0f)!=8: return False
        if ((cmf<<8)+flg)%31!=0: return False
        return True
    def is_zip(data): return data.startswith(b'PK\x03\x04')
